USE flexible_employment;

ON DUPLICATE KEY UPDATE company_name = VALUES(company_name), industry = VALUES(industry), description = VALUES(description), audit_status = 1, status = 1;

ON DUPLICATE KEY UPDATE title = VALUES(title), industry = VALUES(industry), job_type = VALUES(job_type), salary_min = VALUES(salary_min), salary_max = VALUES(salary_max), salary_unit = VALUES(salary_unit), work_city = VALUES(work_city), work_address = VALUES(work_address), description = VALUES(description), requirement = VALUES(requirement), recruit_count = VALUES(recruit_count), audit_status = 1, status = 1, publish_time = VALUES(publish_time);
